<script lang="ts">
 import {enhance} from '$app/forms';import {onMount} from 'svelte';import {Clock,Users,ClipboardCheck,FileOutput,Sparkles} from 'lucide-svelte';import FieldClock from './FieldClock.svelte';import type {PayrollWorkspace} from '$lib/payroll';
 let {data,form}:{data:{workspace:PayrollWorkspace;basePath:string;tenant:string};form?:any}=$props();let w=$derived(data.workspace);let ready=$state(false);let tab=$state('My time');let selectedCrew=$state('');onMount(()=>{ready=true;});
 const tabs=$derived(['My time',...(w.grants['time.crew']?['Crew']:[]),...(w.grants['time.approve']?['Review']:[]),...(w.grants['payroll.compensation.read']?['Payroll']:[]),'Reports',...(w.grants['payroll.admin']?['Setup']:[])]);
 const jobName=(id:string|null)=>w.jobs.find(j=>j.id===id)?.name||'General work';
</script>
<svelte:head><title>Payroll & Time · TurnKeyOps</title><link rel="manifest" href={`${data.basePath}/payroll/manifest.webmanifest`}/></svelte:head>
<div class="payroll"><header><p class="eyebrow">PAYROLL & TIME</p><h1>Good work. Time accounted for.</h1><p>Capture time in the field. Resolve exceptions. Prepare payroll with confidence.</p></header>
{#if form?.message}<p role={form.failed?'alert':'status'} class="notice">{form.message}</p>{/if}
<nav aria-label="Payroll workspace">{#each tabs as label}<button disabled={!ready} class:chosen={tab===label} aria-pressed={tab===label} onclick={()=>tab=label}>{#if label==='My time'}<Clock size={16} aria-hidden="true"/>{:else if label==='Crew'}<Users size={16} aria-hidden="true"/>{:else if label==='Review'}<ClipboardCheck size={16} aria-hidden="true"/>{:else if label==='Payroll'}<FileOutput size={16} aria-hidden="true"/>{/if}{label}</button>{/each}</nav>
{#if !w.configuration.enabled}<section><h2>Payroll & Time is ready to configure</h2><p>A tenant owner can enable this module in Setup. Jobs, Finance and Scheduling are optional integrations.</p></section>{/if}
{#if tab==='My time'}
 <FieldClock workspace={w} tenant={data.tenant}/>
 <section><h2>My recorded time</h2>{#each w.time.filter(t=>t.employeeId===w.employeeId) as t}<article><h3>{t.workDate} · {jobName(t.jobId)}</h3><p>{t.hours} hours · {t.costCode} · {t.status}{t.correctsId?' · Correction':''}</p><p>{t.notes}</p>{#if ['DRAFT','REJECTED'].includes(t.status)&&w.grants['time.self']}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="targetId" value={t.id}/><input type="hidden" name="reason" value="Employee submits recorded time"/><button name="action" value="submit" disabled={!ready}>Submit time</button></form>{/if}</article>{:else}<p>No recorded time yet.</p>{/each}</section>
 {#if w.grants['time.self']&&w.configuration.enabled}<section><details><summary>Enter time manually</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="action" value="manual"/><label>Work date<input name="date" type="date" required/></label><label>Hours<input name="hours" type="number" min="0.01" max="24" step="0.01" required/></label>{#if w.configuration.jobsEnabled&&w.configuration.integrateJobs!==false}<label>Job<select name="jobId"><option value="">General work</option>{#each w.jobs as j}<option value={j.id}>{j.name}</option>{/each}</select></label>{/if}<label>Task / cost code<select name="costCode">{#each w.configuration.costCodes as code}<option>{code}</option>{/each}</select></label><label>Labor classification<select name="classification">{#each w.configuration.classifications as code}<option>{code}</option>{/each}</select></label><label>Earnings type<select name="earningType">{#each w.configuration.earningsTypes.filter(e=>!['OVERTIME','DOUBLE_TIME'].includes(e)) as code}<option>{code}</option>{/each}</select></label><label>Time evidence / reason<input name="reason" required maxlength="2000"/></label><button disabled={!ready}>Save draft time</button></form></details></section>
 <section><details><summary>Request time off</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="action" value="leave"/><label>Date<input name="date" type="date" required/></label><label>Hours<input name="hours" type="number" min="0.01" max="24" step="0.01" required/></label><label>Leave category<select name="leaveType">{#each w.configuration.leaveTypes as type}<option>{type}</option>{/each}</select></label><label>Reason<input name="reason" required/></label><button disabled={!ready}>Request time off</button></form></details>{#each w.leave.filter(l=>l.employeeId===w.employeeId) as leave}<p>{leave.date} · {leave.type} · {leave.hours} hours · {leave.status}</p>{/each}</section>{/if}
{:else if tab==='Crew'}
 <section><h2>Record crew time</h2><p>One shared allocation, with individual hour overrides.</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="action" value="crew-time"/><label>Crew<select name="targetId" bind:value={selectedCrew} required><option value="">Choose crew</option>{#each w.crews as crew}<option value={crew.id}>{crew.name}</option>{/each}</select></label><label>Work date<input name="date" type="date" required/></label><label>Shared hours<input name="hours" type="number" min="0.01" max="24" step="0.01" required/></label>{#if w.configuration.jobsEnabled&&w.configuration.integrateJobs!==false}<label>Job<select name="jobId"><option value="">General work</option>{#each w.jobs as j}<option value={j.id}>{j.name}</option>{/each}</select></label>{/if}<label>Cost code<select name="costCode">{#each w.configuration.costCodes as code}<option>{code}</option>{/each}</select></label><label>Classification<select name="classification">{#each w.configuration.classifications as code}<option>{code}</option>{/each}</select></label>{#each w.crews.find(c=>c.id===selectedCrew)?.members||[] as id}<label>Override hours · {id}<input name={`hours.${id}`} type="number" min="0.01" max="24" step="0.01" placeholder="Use shared hours"/></label>{/each}<label>Crew evidence<input name="reason" required/></label><button disabled={!ready}>Create crew drafts</button></form></section>
{:else if tab==='Review'}
 <section><h2>Needs attention</h2>{#each w.exceptions as exception}<p><a href={`#time-${exception.id}`}>{exception.id}</a> · {exception.issues.join(' · ')}</p>{:else}<p>No recorded time exceptions.</p>{/each}<form method="POST" action="?/save" use:enhance><input type="hidden" name="action" value="bob"/><button disabled={!ready}><Sparkles size={16} aria-hidden="true"/>Bob payroll readiness</button></form>{#if form?.readiness}<p>Bob checked the records visible to your role. Review the exception queue and original time before making changes.</p>{/if}</section>
 <section><h2>Time approval queue</h2>{#each w.time.filter(t=>['SUBMITTED','NEEDS_REVIEW'].includes(t.status)) as t}<article id={`time-${t.id}`}><h3>{t.workDate} · {jobName(t.jobId)}</h3><p>{t.employeeId} · {t.hours} hours · {t.status} · {t.costCode}</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="targetId" value={t.id}/><label>Review evidence / exception resolution<input name="reason" required/></label><button name="action" value="approve" disabled={!ready||t.employeeId===w.employeeId}>Approve time</button><button name="action" value="reject" disabled={!ready}>Return for correction</button></form></article>{:else}<p>No submitted time awaits approval.</p>{/each}</section>
 <section><h2>Corrections and adjustments</h2><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><label>Original entry<select name="targetId" required>{#each w.time.filter(t=>!['ACTIVE','CORRECTED','VOID'].includes(t.status)) as t}<option value={t.id}>{t.workDate} · {t.employeeId} · {t.hours} · {t.status}</option>{/each}</select></label><label>Employee<select name="employeeId">{#each w.employees as e}<option value={e.employeeId}>{e.employeeId}</option>{/each}</select></label><label>Correction work date / next-period adjustment date<input name="date" type="date" required/></label><label>Replacement hours / signed adjustment hours<input name="hours" type="number" min="-24" max="24" step="0.01" required/></label>{#if w.configuration.jobsEnabled&&w.configuration.integrateJobs!==false}<label>Job<select name="jobId"><option value="">General work</option>{#each w.jobs as j}<option value={j.id}>{j.name}</option>{/each}</select></label>{/if}<label>Cost code<select name="costCode">{#each w.configuration.costCodes as code}<option>{code}</option>{/each}</select></label><label>Classification<select name="classification">{#each w.configuration.classifications as code}<option>{code}</option>{/each}</select></label><label>Correction reason<input name="reason" required/></label><button name="action" value="correct" disabled={!ready}>Create replacement draft</button><button name="action" value="adjustment" disabled={!ready}>Create exported-time adjustment</button></form></section>
 <section><h2>Time-off requests</h2>{#each w.leave.filter(l=>l.status==='REQUESTED') as leave}<article><p>{leave.employeeId} · {leave.date} · {leave.hours} hours · {leave.type}</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="targetId" value={leave.id}/><label>Decision reason<input name="reason" required/></label><button name="action" value="approve-leave" disabled={!ready}>Approve leave</button><button name="action" value="reject-leave" disabled={!ready}>Reject leave</button></form></article>{/each}</section>
{:else if tab==='Payroll'}
 <section><h2>Payroll periods</h2>{#each w.periods as period}<article><h3>{period.start} – {period.end}</h3><p>Pay date {period.payDate} · {period.status}</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="targetId" value={period.id}/><label>Preparation / period reason<input name="reason" required/></label>{#if w.grants['payroll.prepare']}<button name="action" value="prepare" disabled={!ready}>Prepare payroll batch</button><button name="action" value="bob-prepare" disabled={!ready}>Ask Bob to prepare a proposal</button>{/if}{#if w.grants['payroll.admin']}<button name="action" value="close-period" disabled={!ready}>Close reconciled period</button>{#if period.status==='CLOSED'}<button name="action" value="reopen-period" disabled={!ready}>Reopen period</button>{/if}{/if}</form></article>{:else}<p>Create the first payroll period in Setup.</p>{/each}</section>
 {#if form?.bob?.status==='proposed'}<section><h2>Bob payroll proposal</h2><p>Prepare payroll from approved time. Permission, period version and readiness will be checked again when approved.</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="action" value="approve-bob"/><input type="hidden" name="bobId" value={form.bob.id}/><button disabled={!ready}>Approve Bob payroll preparation</button></form></section>{/if}
 <section><h2>Prepared batches</h2>{#each w.batches as batch}<article><h3>Batch {batch.id}</h3><p>Version {batch.exportVersion} · {batch.status} · {batch.lines.reduce((n,l)=>n+l.hours,0)} hours · Gross {batch.lines.reduce((n,l)=>n+(l.gross||0),0).toFixed(2)}</p><p class="hash">Calculation evidence {batch.calculationHash}</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="targetId" value={batch.id}/><label>Export / reconciliation evidence<input name="reason" required/></label>{#if batch.status==='PREPARED'&&w.grants['payroll.export']}<button name="action" value="export" disabled={!ready}>Approve immutable CSV export</button>{/if}{#if batch.status==='PREPARED'&&w.grants['payroll.prepare']}<button name="action" value="void-batch" disabled={!ready}>Void unexported batch</button>{/if}{#if batch.status==='EXPORTED'&&w.grants['payroll.results']}<button name="action" value="reconcile" disabled={!ready}>Reconcile exact provider results</button>{/if}</form>{#if ['EXPORTED','PROCESSED'].includes(batch.status)&&w.grants['payroll.export']}<a href={`${data.basePath}/payroll/export?batch=${batch.id}`}>Download payroll CSV · version {batch.exportVersion}</a>{/if}{#each w.reconciliation.find(r=>r.id===batch.id)?.issues||[] as issue}<p>{issue}</p>{/each}
 {#if w.grants['payroll.results']}<details><summary>Import provider actuals</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="targetId" value={batch.id}/><label>Normalized provider result JSON<textarea name="actuals" required placeholder="Paste normalized provider result records"></textarea></label><label>Import source evidence<input name="reason" required/></label><button name="action" value="import-results" disabled={!ready}>Import provider results</button><button name="action" value="correct-result" disabled={!ready}>Import reviewed result correction</button><p>Corrections require a new result ID and source key, plus correctsId referencing the original result. Originals remain in history.</p></form></details>{/if}</article>{:else}<p>No prepared batches.</p>{/each}</section>
{#if w.configuration.financeEnabled&&w.configuration.integrateFinance!==false}<section><h2>Optional Finance integration</h2><p>Finance control and compensation permissions are required. Payroll capture and export work independently.</p><form method="POST" action="?/save" use:enhance><button name="action" value="finance-context" disabled={!ready}>Review Finance integration</button></form>{#if form?.financeContext}<form method="POST" action="?/save" use:enhance><input type="hidden" name="action" value="finance-consume"/><input type="hidden" name="financeVersion" value={form.financeContext.version}/><label>Payroll batch<select name="targetId">{#each w.batches.filter(b=>b.status!=='VOID') as batch}<option value={batch.id}>{batch.id} · {batch.status}</option>{/each}</select></label><label>Accounting stage<select name="stage"><option value="estimate">Accrue prepared loaded labor cost</option><option value="actual">Reconcile exact processed provider actuals</option></select></label><label>Accounting date<input name="date" type="date" required/></label><label>Dedicated payroll liability<select name="liabilityAccount">{#each form.financeContext.accounts as account}<option value={account.code}>{account.code} · {account.name}</option>{/each}</select></label><label>Accounting review evidence<input name="reason" required/></label><button disabled={!ready}>Consume payroll event in Finance</button></form>{/if}</section>{/if}
{:else if tab==='Reports'}
 <section><h2>Recorded labor hours</h2><p>Approved Job and cost-code totals preserve source entry IDs. Active clocks have no finalized duration.</p><!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable reports need keyboard focus.) -->
 <section class="table" tabindex="0" aria-label="Labor hours report"><table><caption>Hours by employee</caption><thead><tr><th scope="col">Employee</th><th scope="col">Hours</th></tr></thead><tbody>{#each w.reports.byEmployee as row}<tr><th scope="row">{row.employeeId}</th><td>{row.hours}</td></tr>{/each}</tbody></table></section><h3>Projected earnings hours</h3><p>Configured classifications of recorded time, including drafts awaiting approval. These are not processed payroll.</p>{#each w.earningsPreview?.filter(e=>['OVERTIME','DOUBLE_TIME'].includes(e.type))||[] as earning}<p>{earning.date} · {earning.employeeId} · {earning.type} · {earning.hours} hours · Source {earning.timeId}</p>{:else}<p>No projected premium hours in the recorded time.</p>{/each}<h3>Approved hours by Job</h3>{#each w.reports.byJob as row}<p>{jobName(row.jobId)} · {row.hours}</p>{/each}<h3>Approved hours by cost code</h3>{#each w.reports.byCostCode as row}<p>{row.costCode} · {row.hours}</p>{/each}<h3>Approved hours by trade</h3>{#each w.reports.byTrade as row}<p>{row.trade||'Unspecified trade'} · {row.hours}</p>{/each}</section>
{:else if tab==='Setup'}
 <section><h2>Module configuration</h2><p>Enable Payroll independently. Configure overtime thresholds from your reviewed tenant policy; unset thresholds do not infer a jurisdiction rule. Activity codes work without Finance.</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="action" value="configure"/><fieldset><legend>Module and optional integrations</legend>{#each [{key:'enabled',label:'Enable Payroll & Time'},{key:'jobsEnabled',label:'Jobs product enabled'},{key:'integrateJobs',label:'Exchange allocations with Jobs'},{key:'financeEnabled',label:'Finance product enabled'},{key:'integrateFinance',label:'Allow Finance event consumption'},{key:'schedulingEnabled',label:'Scheduling product enabled'},{key:'integrateScheduling',label:'Exchange schedule context and time-off availability'},{key:'requireJob',label:'Require a Job allocation'},{key:'requireCostCode',label:'Require an activity code'},{key:'crewTimeEnabled',label:'Enable crew time'}] as item}<label class="check"><input type="checkbox" name={item.key} checked={w.configuration[item.key as keyof typeof w.configuration]===true}/>{item.label}</label>{/each}</fieldset><label>Timezone<input name="timezone" value={w.configuration.timezone} required/></label><label>Pay frequency<select name="frequency" value={w.configuration.frequency}><option>WEEKLY</option><option>BIWEEKLY</option><option>SEMIMONTHLY</option><option>MONTHLY</option></select></label><label>Week starts<select name="weekStart" value={w.configuration.weekStart}>{#each ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'] as day,i}<option value={i}>{day}</option>{/each}</select></label><label>Weekly overtime after hours<input type="number" name="weeklyOvertime" min="1" max="168" step="0.01" value={w.configuration.weeklyOvertime??''}/></label><label>Daily overtime after hours<input type="number" name="dailyOvertime" min="1" max="24" step="0.01" value={w.configuration.dailyOvertime??''}/></label><label>Daily double time after hours<input type="number" name="dailyDoubleTime" min="1" max="24" step="0.01" value={w.configuration.dailyDoubleTime??''}/></label><label class="check"><input type="checkbox" name="seventhDayOvertime" checked={w.configuration.seventhDayOvertime}/>Seventh consecutive day overtime</label><label>Overtime multiplier<input name="overtimeMultiplier" type="number" min="1" step="0.01" value={w.configuration.overtimeMultiplier}/></label><label>Double time multiplier<input name="doubleTimeMultiplier" type="number" min="1" step="0.01" value={w.configuration.doubleTimeMultiplier}/></label><label>Activity codes, one per line<textarea name="costCodes" required>{w.configuration.costCodes.join('\n')}</textarea></label><label>Labor classifications, one per line<textarea name="classifications" required>{w.configuration.classifications.join('\n')}</textarea></label><label>Earnings types, one per line<textarea name="earningsTypes" required>{w.configuration.earningsTypes.join('\n')}</textarea></label><label>Leave categories, one per line<textarea name="leaveTypes" required>{w.configuration.leaveTypes.join('\n')}</textarea></label><fieldset><legend>Provider earning mappings · generic CSV</legend>{#each w.configuration.earningsTypes as type}<label>Provider code for {type}<input name={`mapping.${type}`} value={w.configuration.earningsMapping[type]||''}/></label>{/each}</fieldset><label>Meal break warning after worked hours<input name="mealBreakRequiredAfterHours" type="number" min="1" max="24" step="0.01" value={w.configuration.mealBreakRequiredAfterHours??''}/></label><label>Minimum meal break minutes<input name="mealBreakMinimumMinutes" type="number" min="1" max="120" value={w.configuration.mealBreakMinimumMinutes??30}/></label><label>Clock location policy<select name="locationPolicy" value={w.configuration.locationPolicy}><option value="OFF">Off</option><option value="CAPTURE">Capture with employee permission</option><option value="REQUIRE_WITH_OVERRIDE">Require location or an explicit override note</option></select></label><p>Location is requested only with a clock event. No continuous tracking.</p><label>Configuration reason<input name="reason" required/></label><button disabled={!ready}>Save tenant payroll configuration</button></form></section>
 <section><h2>Create payroll period</h2><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="action" value="period"/><label>Start<input name="start" type="date" required/></label><label>End<input name="end" type="date" required/></label><label>Pay date<input name="payDate" type="date" required/></label><label>Cutoff<input name="cutoff" type="datetime-local" required/></label><label>Period reason<input name="reason" required/></label><button disabled={!ready}>Create payroll period</button></form></section>
 <section><h2>Crews</h2><p>Existing iBeam company members; no duplicate employee identities.</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="action" value="crew"/><label>Crew name<input name="name" required/></label><label>Effective from<input name="date" type="date" required/></label><label>Crew lead<select name="leadId">{#each w.employees as e}<option value={e.employeeId}>{e.employeeId}</option>{/each}</select></label><fieldset><legend>Crew members, including lead</legend>{#each w.employees as e}<label class="check"><input type="checkbox" name="members" value={e.employeeId}/>{e.employeeId}</label>{/each}</fieldset><label>Reason<input name="reason" required/></label><button disabled={!ready}>Save crew</button></form></section>
 {#if w.grants['payroll.compensation.read']}<section><h2>Secure employee payroll profiles</h2>{#each w.profiles as profile}<p>{profile.employeeId} · {profile.payType} · Effective {profile.effectiveDate} · {profile.payRate??profile.salaryPerPeriod}</p>{/each}<form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="action" value="profile"/><label>Employee<select name="employeeId">{#each w.employees as e}<option value={e.employeeId}>{e.employeeId}</option>{/each}</select></label><label>Effective date<input name="date" type="date" required/></label><label>Pay type<select name="payType"><option>HOURLY</option><option>SALARY</option></select></label><label>Hourly pay rate<input name="payRate" type="number" min="0" step="0.01"/></label><label>Salary per payroll period<input name="salaryPerPeriod" type="number" min="0" step="0.01"/></label><label>Loaded labor cost rate<input name="laborCostRate" type="number" min="0" step="0.01"/></label><label class="check"><input name="overtimeEligible" type="checkbox" checked/>Overtime eligible</label><label>Classification<select name="classification">{#each w.configuration.classifications as value}<option>{value}</option>{/each}</select></label><label>Provider employee ID<input name="providerEmployeeId" required/></label><label>Department<input name="department"/></label><label>Compensation authorization<input name="reason" required/></label><button disabled={!ready}>Add effective payroll profile</button></form></section>{/if}
 <section><details><summary>Import existing time</summary><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="action" value="import-time"/><label>Normalized time entries JSON<textarea name="entries" required></textarea></label><label>Import source evidence<input name="reason" required/></label><button disabled={!ready}>Import time drafts</button></form></details></section>
 <section><details><summary>Configured prevailing wage foundation</summary><p>Tenant-provided requirements with an authority reference. No government rates or filing are inferred.</p><form method="POST" action="?/save" use:enhance><input type="hidden" name="version" value={w.version}/><input type="hidden" name="action" value="wage-requirement"/><label>Wage requirement JSON<textarea name="wageRequirement" required></textarea></label><label>Authoritative source evidence<input name="reason" required/></label><button disabled={!ready}>Add wage requirement</button></form></details></section>
{/if}
</div>
<style>
.payroll{color:var(--text-strong,#172e32);max-width:80rem;margin:auto}.eyebrow{color:#0f766e;font-size:.8rem;font-weight:700;letter-spacing:.12em}h1{font-size:clamp(1.8rem,4vw,2.7rem);line-height:1.15;margin:.4rem 0}header{margin-bottom:1.5rem}nav{display:flex;gap:.5rem;flex-wrap:wrap;margin:1.5rem 0}section{padding:1.3rem;margin:1.2rem 0;border:1px solid var(--border,#cbd5e1);border-radius:.8rem;background:var(--surface,#fff)}h2{font-size:1.3rem;margin:0 0 .8rem}h3{font-size:1rem}article{padding:1rem 0;border-bottom:1px solid #94a3b8}form{display:flex;flex-wrap:wrap;gap:.8rem;align-items:end}label{display:flex;flex-direction:column;gap:.4rem;min-width:12rem;flex:1;font-size:.9rem}input,select,textarea{min-height:44px;border:1px solid #64748b;border-radius:.4rem;padding:.6rem;background:var(--surface,#fff);color:inherit;width:100%}textarea{min-height:8rem;font-family:monospace}label:has(textarea){flex-basis:100%}button{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;min-height:44px;padding:.65rem 1rem;border:1px solid #64748b;border-radius:.5rem;cursor:pointer;background:transparent;color:inherit}form button{background:#c2410c;border-color:#c2410c;color:#fff}button.chosen{background:#0f766e;color:#fff;border-color:#0f766e}button:disabled{opacity:.55;cursor:not-allowed}.check{flex-direction:row;align-items:center}.check input{width:1.2rem;min-height:1.2rem}.notice{padding:1rem;border-left:3px solid #0f766e}p,.hash{overflow-wrap:anywhere}.table{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:.7rem;text-align:left;border-bottom:1px solid #94a3b8}summary{cursor:pointer;min-height:44px;padding:.6rem 0}a{color:#0f766e;text-decoration:underline}:is(button,input,select,textarea,summary,a,.table):focus-visible{outline:3px solid #0d9488;outline-offset:3px}:global(.dark) .payroll,:global([data-theme='dark']) .payroll{color:#e2e8f0}:global(.dark) section,:global([data-theme='dark']) section,:global(.dark) input,:global(.dark) select,:global(.dark) textarea,:global([data-theme='dark']) input,:global([data-theme='dark']) select,:global([data-theme='dark']) textarea{background:#12282d;color:#e2e8f0}:global(.dark) a,:global(.dark) .eyebrow,:global([data-theme='dark']) a,:global([data-theme='dark']) .eyebrow{color:#5eead4}@media(max-width:600px){label{min-width:100%}form button{width:100%}section{padding:1rem}}
</style>
